use std::{
    collections::BTreeMap,
    fs::{self, File},
    io::{BufWriter, Write},
    path::{Path, PathBuf},
};

use clap::Parser;
use serde::{Deserialize, Serialize};

#[derive(Debug, Parser)]
#[command(
    name = "catalog-audit",
    about = "Analyze duplicate paths in a WoW MPQ catalog without choosing archive winners"
)]
struct Args {
    /// Existing schema-v2 catalog generated by wow-mpq-inspector.
    #[arg(long)]
    catalog: PathBuf,

    /// Destination for the detailed JSON duplicate report.
    #[arg(long)]
    json: PathBuf,

    /// Optional normalized CSV with one row per duplicate provider.
    #[arg(long)]
    csv: Option<PathBuf>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct InputCatalog {
    schema_version: u32,
    archives: Vec<InputArchive>,
    files: Vec<InputFile>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct InputArchive {
    path: String,
    layer_category: String,
    status: String,
}

#[derive(Debug, Deserialize)]
struct InputFile {
    path: String,
    /// [archiveIndex, uncompressedSizeBytes, compressedSizeBytes, flags]
    providers: Vec<[u64; 4]>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct AuditReport {
    schema_version: u32,
    source_catalog_schema_version: u32,
    total_catalog_paths: usize,
    duplicate_paths: usize,
    duplicate_provider_records: usize,
    character_model_duplicate_paths: usize,
    by_extension: Vec<ExtensionSummary>,
    archive_pairs: Vec<ArchivePairSummary>,
    character_model_examples: Vec<DuplicateFile>,
    duplicates: Vec<DuplicateFile>,
    notes: Vec<String>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct ExtensionSummary {
    extension: String,
    duplicate_paths: usize,
    provider_records: usize,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct ArchivePairSummary {
    archive_a: String,
    archive_b: String,
    shared_duplicate_paths: usize,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct DuplicateFile {
    path: String,
    extension: String,
    provider_count: usize,
    resolution_status: &'static str,
    winner: Option<String>,
    providers: Vec<ArchiveProvider>,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct ArchiveProvider {
    archive_index: usize,
    archive_path: String,
    archive_category: String,
    archive_status: String,
    uncompressed_size_bytes: u64,
    compressed_size_bytes: u64,
    flags: u64,
}

#[derive(Debug, Default)]
struct ExtensionAccumulator {
    duplicate_paths: usize,
    provider_records: usize,
}

fn main() {
    if let Err(error) = run() {
        eprintln!("error: {error}");
        std::process::exit(1);
    }
}

fn run() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();
    let input_file = File::open(&args.catalog)?;
    let catalog: InputCatalog = serde_json::from_reader(input_file)?;
    let report = build_report(&catalog)?;

    write_json(&args.json, &report)?;
    if let Some(csv_path) = &args.csv {
        write_csv(csv_path, &report.duplicates)?;
    }

    println!("WoW MPQ Catalog Audit");
    println!("=====================");
    println!("Catalog schema:           {}", report.source_catalog_schema_version);
    println!("Catalog paths:            {}", report.total_catalog_paths);
    println!("Duplicate paths:          {}", report.duplicate_paths);
    println!("Duplicate provider rows:  {}", report.duplicate_provider_records);
    println!("Duplicate M2 paths:       {}", report.character_model_duplicate_paths);
    println!("Archive pairs:            {}", report.archive_pairs.len());
    println!("JSON report:              {}", args.json.display());
    if let Some(csv_path) = args.csv {
        println!("CSV report:               {}", csv_path.display());
    }
    println!("Winning archives:         not inferred");

    Ok(())
}

fn build_report(catalog: &InputCatalog) -> Result<AuditReport, Box<dyn std::error::Error>> {
    if catalog.schema_version != 2 {
        return Err(format!(
            "Unsupported catalog schema version {}. Expected schema version 2.",
            catalog.schema_version
        )
        .into());
    }

    let mut extension_counts: BTreeMap<String, ExtensionAccumulator> = BTreeMap::new();
    let mut pair_counts: BTreeMap<(String, String), usize> = BTreeMap::new();
    let mut duplicates = Vec::new();
    let mut duplicate_provider_records = 0usize;
    let mut character_model_duplicate_paths = 0usize;

    for file in &catalog.files {
        if file.providers.len() < 2 {
            continue;
        }

        let extension = file_extension(&file.path);
        let mut providers = Vec::with_capacity(file.providers.len());

        for tuple in &file.providers {
            let archive_index = usize::try_from(tuple[0])?;
            let archive = catalog.archives.get(archive_index).ok_or_else(|| {
                format!(
                    "Path '{}' refers to archive index {}, but the catalog contains only {} archives.",
                    file.path,
                    archive_index,
                    catalog.archives.len()
                )
            })?;

            providers.push(ArchiveProvider {
                archive_index,
                archive_path: archive.path.clone(),
                archive_category: archive.layer_category.clone(),
                archive_status: archive.status.clone(),
                uncompressed_size_bytes: tuple[1],
                compressed_size_bytes: tuple[2],
                flags: tuple[3],
            });
        }

        let count = providers.len();
        let extension_summary = extension_counts.entry(extension.clone()).or_default();
        extension_summary.duplicate_paths += 1;
        extension_summary.provider_records += count;
        duplicate_provider_records += count;

        if extension == "m2" {
            character_model_duplicate_paths += 1;
        }

        for left in 0..providers.len() {
            for right in (left + 1)..providers.len() {
                let mut archive_names = [
                    providers[left].archive_path.clone(),
                    providers[right].archive_path.clone(),
                ];
                archive_names.sort();
                *pair_counts
                    .entry((archive_names[0].clone(), archive_names[1].clone()))
                    .or_default() += 1;
            }
        }

        duplicates.push(DuplicateFile {
            path: file.path.clone(),
            extension,
            provider_count: count,
            resolution_status: "unresolved",
            winner: None,
            providers,
        });
    }

    duplicates.sort_by(|left, right| {
        left.path
            .to_ascii_lowercase()
            .cmp(&right.path.to_ascii_lowercase())
    });

    let by_extension = extension_counts
        .into_iter()
        .map(|(extension, counts)| ExtensionSummary {
            extension,
            duplicate_paths: counts.duplicate_paths,
            provider_records: counts.provider_records,
        })
        .collect();

    let mut archive_pairs = pair_counts
        .into_iter()
        .map(|((archive_a, archive_b), shared_duplicate_paths)| ArchivePairSummary {
            archive_a,
            archive_b,
            shared_duplicate_paths,
        })
        .collect::<Vec<_>>();
    archive_pairs.sort_by(|left, right| {
        right
            .shared_duplicate_paths
            .cmp(&left.shared_duplicate_paths)
            .then_with(|| left.archive_a.cmp(&right.archive_a))
            .then_with(|| left.archive_b.cmp(&right.archive_b))
    });

    let character_model_examples = duplicates
        .iter()
        .filter(|duplicate| duplicate.extension == "m2")
        .take(30)
        .cloned()
        .collect();

    Ok(AuditReport {
        schema_version: 1,
        source_catalog_schema_version: catalog.schema_version,
        total_catalog_paths: catalog.files.len(),
        duplicate_paths: duplicates.len(),
        duplicate_provider_records,
        character_model_duplicate_paths,
        by_extension,
        archive_pairs,
        character_model_examples,
        duplicates,
        notes: vec![
            "This report analyzes catalog metadata only; it does not extract asset payloads or modify MPQ archives.".to_owned(),
            "Provider order and archiveIndex reflect catalog enumeration order, not the client's effective archive load order.".to_owned(),
            "Archive layer categories are descriptive labels and are not a precedence ranking.".to_owned(),
            "No winning archive is selected. Every duplicate remains unresolved until the exact client loader behavior is verified.".to_owned(),
            "Only named paths discoverable through archive listfiles are included in path comparisons.".to_owned(),
        ],
    })
}

fn file_extension(path: &str) -> String {
    let file_name = path
        .rsplit(|character| character == '/' || character == '\\')
        .next()
        .unwrap_or(path);
    match file_name.rsplit_once('.') {
        Some((stem, extension)) if !stem.is_empty() && !extension.is_empty() => {
            extension.to_ascii_lowercase()
        }
        _ => "[no-extension]".to_owned(),
    }
}

fn write_json(path: &Path, report: &AuditReport) -> Result<(), Box<dyn std::error::Error>> {
    create_parent_directory(path)?;
    let file = File::create(path)?;
    let mut writer = BufWriter::new(file);
    serde_json::to_writer(&mut writer, report)?;
    writer.write_all(b"\n")?;
    writer.flush()?;
    Ok(())
}

fn write_csv(
    path: &Path,
    duplicates: &[DuplicateFile],
) -> Result<(), Box<dyn std::error::Error>> {
    create_parent_directory(path)?;
    let file = File::create(path)?;
    let mut writer = BufWriter::new(file);

    writeln!(
        writer,
        "path,extension,provider_count,archive_index,archive_path,archive_category,archive_status,uncompressed_size_bytes,compressed_size_bytes,flags,resolution_status"
    )?;

    for duplicate in duplicates {
        for provider in &duplicate.providers {
            let values = [
                duplicate.path.clone(),
                duplicate.extension.clone(),
                duplicate.provider_count.to_string(),
                provider.archive_index.to_string(),
                provider.archive_path.clone(),
                provider.archive_category.clone(),
                provider.archive_status.clone(),
                provider.uncompressed_size_bytes.to_string(),
                provider.compressed_size_bytes.to_string(),
                provider.flags.to_string(),
                duplicate.resolution_status.to_owned(),
            ];
            let row = values
                .iter()
                .map(|value| csv_escape(value))
                .collect::<Vec<_>>()
                .join(",");
            writeln!(writer, "{row}")?;
        }
    }

    writer.flush()?;
    Ok(())
}

fn csv_escape(value: &str) -> String {
    if value
        .chars()
        .any(|character| matches!(character, ',' | '"' | '\n' | '\r'))
    {
        format!("\"{}\"", value.replace('"', "\"\""))
    } else {
        value.to_owned()
    }
}

fn create_parent_directory(path: &Path) -> std::io::Result<()> {
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        fs::create_dir_all(parent)?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_catalog() -> InputCatalog {
        serde_json::from_str(
            r#"{
                "schemaVersion": 2,
                "archives": [
                    {"path":"Data/common-2.mpq","layerCategory":"global-base","status":"opened"},
                    {"path":"Data/patch-a.mpq","layerCategory":"global-patch","status":"opened"},
                    {"path":"Data/enUS/patch-enUS-Z.MPQ","layerCategory":"locale-patch","status":"opened"}
                ],
                "files": [
                    {"path":"Character/Human/Female/HumanFemale.M2","providers":[[0,1000,500,1],[1,2000,900,1]]},
                    {"path":"Interface\\Icons\\Spell.blp","providers":[[0,100,50,2]]}
                ]
            }"#,
        )
        .unwrap()
    }

    #[test]
    fn reports_duplicates_without_inventing_a_winner() {
        let report = build_report(&sample_catalog()).unwrap();

        assert_eq!(report.duplicate_paths, 1);
        assert_eq!(report.duplicate_provider_records, 2);
        assert_eq!(report.character_model_duplicate_paths, 1);
        assert_eq!(report.duplicates[0].path, "Character/Human/Female/HumanFemale.M2");
        assert_eq!(report.duplicates[0].resolution_status, "unresolved");
        assert!(report.duplicates[0].winner.is_none());
    }

    #[test]
    fn resolves_archive_indices_to_paths_without_reordering_providers() {
        let report = build_report(&sample_catalog()).unwrap();
        let providers = &report.duplicates[0].providers;

        assert_eq!(providers[0].archive_path, "Data/common-2.mpq");
        assert_eq!(providers[1].archive_path, "Data/patch-a.mpq");
    }

    #[test]
    fn counts_shared_paths_for_each_archive_pair() {
        let report = build_report(&sample_catalog()).unwrap();

        assert_eq!(report.archive_pairs.len(), 1);
        assert_eq!(report.archive_pairs[0].archive_a, "Data/common-2.mpq");
        assert_eq!(report.archive_pairs[0].archive_b, "Data/patch-a.mpq");
        assert_eq!(report.archive_pairs[0].shared_duplicate_paths, 1);
    }

    #[test]
    fn handles_windows_paths_and_case_insensitive_extensions() {
        assert_eq!(file_extension("Character\\Human\\Female\\HumanFemale.M2"), "m2");
    }

    #[test]
    fn escapes_csv_values_containing_commas_and_quotes() {
        assert_eq!(csv_escape("file, name\""), "\"file, name\"\"\"");
        assert_eq!(csv_escape("plain-name"), "plain-name");
    }

    #[test]
    fn rejects_catalogs_with_an_unsupported_schema() {
        let mut catalog = sample_catalog();
        catalog.schema_version = 3;

        assert!(build_report(&catalog).is_err());
    }

    #[test]
    fn rejects_provider_indices_outside_the_archive_list() {
        let mut catalog = sample_catalog();
        catalog.files[0].providers[0][0] = 99;

        assert!(build_report(&catalog).is_err());
    }
}
